1	#!/usr/bin/env bun
2	/**
3	 * build-dist.ts — Bundles every deployable entry-point script from its `src/`
4	 * source into the deployed tree it mirrors.
5	 *
6	 * The deployed tree has two roots, and which one a thing lands in is the whole
7	 * layout: `.github/atomaton/` is the adopter's, `.github/atomaton-runtime/` is ours.
8	 *
9	 *   - `src/entrypoints/machinery/**` (the glue a `*.wac.ts` file's `run:` step invokes)
10	 *     -> `dist/.github/atomaton-runtime/scripts/`.
11	 *   - `src/entrypoints/tools/**` (the MCP servers and hooks `atoma` starts)
12	 *     -> `dist/.github/atomaton-runtime/tools/`, with `defaults.yaml` and
13	 *     `packages.json` copied beside them.
14	 *   - `src/content/**` (config, prompt template, agent definitions, skills,
15	 *     rulesets) -> `dist/.github/atomaton/`, copied verbatim.
16	 *
17	 * The tools file the core reads is NOT built here and does not ship: it is
18	 * written per run by `scripts/write_tools_file.ts`, from the config. A generated
19	 * file that is distributed is a second source of truth wearing the clothes of a
20	 * first -- see that script for what it cost.
21	 *
22	 * Every entry point is bundled with ALL of its imports inlined -- including
23	 * the shared `src/lib/**` kernel (so `src/entrypoints/machinery/**` and
24	 * `src/entrypoints/tools/**` can freely import shared code without any
25	 * hand-duplicated files between them) and npm dependencies like
26	 * `@modelcontextprotocol/sdk` (so the deployed output needs no
27	 * `node_modules`/`package.json`/`bun install` step at all -- verified: a
28	 * bundled `mcp/github.ts` runs standalone with zero dependencies nearby).
29	 * Bundled output keeps a `.ts` extension (Bun happily runs plain JS through
30	 * a `.ts`-named file) so every existing `bun run .github/.../foo.ts`
31	 * reference -- in generated workflow YAML, `tools.yaml`, `ScriptRef`'s
32	 * runtime-path derivation -- needs no change.
33	 *
34	 * `.test.ts` files are excluded from entry-point discovery -- tests are a
35	 * dev-time concern for this repo, not something end users need in their
36	 * own `.github/`. `dist/.github/` is fully generated output: nothing under
37	 * it should ever be hand-edited directly.
38	 */
39	import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
40	import { dirname, join } from "node:path";
41	import { fileURLToPath } from "node:url";
42	import { RELEASE_MANIFEST, SCRIPTS_DIR, sourceOf, TOOLS_DIR, USER_ROOT } from "./domain/machinery/machinery-layout.ts";
43	import { buildManifest } from "./domain/machinery/release-manifest.ts";
44	
45	/**
46	 * Packages left out of the bundle and installed on the runner instead.
47	 *
48	 * Everything else is inlined, which is what lets the deployed `.github/` run
49	 * with no `node_modules` beside it. These cannot be: `@huggingface/transformers`
50	 * reaches `onnxruntime-node`, whose `.node` binaries are not JavaScript and so
51	 * are not something a JavaScript bundler can carry. Inlining the wrapper and
52	 * losing the binary produces a script that builds and then fails at its first
53	 * call, which is the worst of both.
54	 *
55	 * Anything added here has to be installed by the runner before an agent starts
56	 * — see `atomaton-runtime/tools/packages.json`'s `bun` list and the step that reads it.
57	 */
58	const RUNTIME_INSTALLED = ["@huggingface/transformers"];
59	
60	const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
61	const SRC_DIR = join(REPO_ROOT, "src");
62	const DIST_GITHUB_DIR = join(REPO_ROOT, "dist", ".github");
63	
64	/**
65	 * Both ends of every tree, from the one table that holds them.
66	 *
67	 * A tree used to be `src/<name>` here and `.github/<name>` deployed, so this file
68	 * derived one from the other by slicing the string. That stopped being true when the
69	 * source was sorted by layer: `content/` deploys to `.github/atomaton/` and
70	 * `entrypoints/machinery/` to `.github/atomaton-runtime/scripts/`, and neither name
71	 * appears in the other.
72	 *
73	 * The correspondence is `BUILT_FROM` in `domain/machinery/machinery-layout.ts`, which
74	 * is where the deployed side was already named. Taken from there rather than spelled
75	 * again beside it: it WAS spelled again -- `join(SRC_DIR, "atoma-runtime", "tools")`
76	 * -- and renaming the constants left this file walking a directory that no longer
77	 * existed. A name broken into path segments is the one form of that duplicate a
78	 * search for the path cannot find.
79	 */
80	const from = (deployed: string): string => join(SRC_DIR, ...sourceOf(deployed).split("/"));
81	const into = (deployed: string): string => join(REPO_ROOT, "dist", ...deployed.split("/"));
82	
83	/** Recursively collects every entry-point `*.ts` file under `dir`, skipping `excludeDirs` (by name, at any depth) and `*.test.ts` files. */
84	function collectEntryPoints(dir: string, excludeDirs: ReadonlySet<string>): string[] {
85	  const results: string[] = [];
86	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
87	    if (entry.isDirectory()) {
88	      if (excludeDirs.has(entry.name)) continue;
89	      results.push(...collectEntryPoints(join(dir, entry.name), excludeDirs));
90	    } else if (entry.isFile() && entry.name.endsWith(".ts") && !entry.name.endsWith(".test.ts")) {
91	      results.push(join(dir, entry.name));
92	    }
93	  }
94	  return results;
95	}
96	
97	/** Bundles every entry point under `srcDir` into `distDir`, preserving its subdirectory structure (e.g. `mcp/github.ts` -> `<distDir>/mcp/github.ts`). */
98	async function bundleTree(srcDir: string, distDir: string, excludeDirs: ReadonlySet<string> = new Set()): Promise<void> {
99	  const entrypoints = collectEntryPoints(srcDir, excludeDirs);
100	  rmSync(distDir, { recursive: true, force: true });
101	
102	  // Build each deployable entry point independently. Imported implementation
103	  // modules live under excluded `lib/` directories and are inlined here.
104	  for (const entrypoint of entrypoints) {
105	    const result = await Bun.build({
106	      entrypoints: [entrypoint],
107	      outdir: distDir,
108	      root: srcDir,
109	      target: "bun",
110	      format: "esm",
111	      naming: "[dir]/[name].ts",
112	      external: RUNTIME_INSTALLED,
113	    });
114	    if (!result.success) {
115	      console.error(`build-dist: bundling failed for ${entrypoint}:`);
116	      for (const log of result.logs) console.error(log);
117	      process.exit(1);
118	    }
119	  }
120	
121	  console.log(`build-dist: bundled ${entrypoints.length} script(s): ${srcDir} -> ${distDir}`);
122	}
123	
124	function copyDirectoryFresh(source: string, destination: string): void {
125	  rmSync(destination, { recursive: true, force: true });
126	  cpSync(source, destination, { recursive: true });
127	}
128	
